package main

import "fmt"

const PerTurn = 3

type Customer struct {
	Name  string
	Items int
}

func main() {
	var q []Customer
	for {
		var c Customer
		if _, err := fmt.Scan(&c.Name, &c.Items); err != nil {
			break
		}
		q = append(q, c) // enqueue at the back
	}

	for len(q) > 0 {
		c := q[0] // dequeue from the front
		q = q[1:]
		if c.Items > PerTurn {
			c.Items -= PerTurn
			q = append(q, c) // not done yet: back of the line
			continue
		}
		fmt.Println(c.Name)
	}
}

