package main

import "fmt"

const PerTurn = 2

type Task struct {
	Name string
	Left int
}

func main() {
	var q []Task
	for {
		var t Task
		if _, err := fmt.Scan(&t.Name, &t.Left); err != nil {
			break
		}
		q = append(q, t)
	}

	clock := 0
	for len(q) > 0 {
		t := q[0]
		q = q[1:]
		run := t.Left
		if run > PerTurn {
			run = PerTurn
		}
		clock += run
		t.Left -= run
		if t.Left > 0 {
			q = append(q, t)
			continue
		}
		fmt.Printf("%s %d\n", t.Name, clock)
	}
}

