package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func shortest(grid []string) int {
	rows, cols := len(grid), len(grid[0])
	dist := make([][]int, rows)
	var q [][2]int
	var target [2]int
	for r := 0; r < rows; r++ {
		dist[r] = make([]int, cols)
		for c := 0; c < cols; c++ {
			dist[r][c] = -1
			switch grid[r][c] {
			case 'S':
				dist[r][c] = 0
				q = append(q, [2]int{r, c})
			case 'E':
				target = [2]int{r, c}
			}
		}
	}

	dr := []int{-1, 1, 0, 0}
	dc := []int{0, 0, -1, 1}
	for len(q) > 0 {
		p := q[0]
		q = q[1:]
		if p == target {
			return dist[p[0]][p[1]] // the first time E comes out is the shortest
		}
		for d := 0; d < 4; d++ {
			nr, nc := p[0]+dr[d], p[1]+dc[d]
			if nr < 0 || nr >= rows || nc < 0 || nc >= cols {
				continue
			}
			if grid[nr][nc] == '#' || dist[nr][nc] != -1 {
				continue
			}
			dist[nr][nc] = dist[p[0]][p[1]] + 1
			q = append(q, [2]int{nr, nc})
		}
	}
	return -1
}

func main() {
	var grid []string
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		if line := strings.TrimSpace(scanner.Text()); line != "" {
			grid = append(grid, line)
		}
	}
	fmt.Println(shortest(grid))
}

