package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func rotMinutes(grid [][]byte) int {
	var q [][2]int
	fresh := 0
	for r := range grid {
		for c := range grid[r] {
			switch grid[r][c] {
			case 'R':
				q = append(q, [2]int{r, c}) // every rotten orange starts in the queue
			case 'F':
				fresh++
			}
		}
	}

	dr := []int{-1, 1, 0, 0}
	dc := []int{0, 0, -1, 1}
	minutes := 0
	for len(q) > 0 && fresh > 0 {
		size := len(q) // this minute's oranges, before any new ones join
		for i := 0; i < size; i++ {
			p := q[0]
			q = q[1:]
			for d := 0; d < 4; d++ {
				nr, nc := p[0]+dr[d], p[1]+dc[d]
				if nr < 0 || nr >= len(grid) || nc < 0 || nc >= len(grid[nr]) {
					continue
				}
				if grid[nr][nc] == 'F' {
					grid[nr][nc] = 'R'
					fresh--
					q = append(q, [2]int{nr, nc})
				}
			}
		}
		minutes++
	}
	if fresh > 0 {
		return -1
	}
	return minutes
}

func main() {
	var grid [][]byte
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		if line := strings.TrimSpace(scanner.Text()); line != "" {
			grid = append(grid, []byte(line))
		}
	}
	fmt.Println(rotMinutes(grid))
}

