package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func burnMinutes(grid [][]byte) int {
	var q [][2]int
	for r := range grid {
		for c := range grid[r] {
			if grid[r][c] == 'F' {
				q = append(q, [2]int{r, c})
			}
		}
	}

	dr := []int{-1, 1, 0, 0}
	dc := []int{0, 0, -1, 1}
	minutes := 0
	for len(q) > 0 {
		size := len(q)
		for i := 0; i < size; i++ {
			p := q[0]
			q = q[1:]
			for d := 0; d < 4; d++ {
				nr, nc := p[0]+dr[d], p[1]+dc[d]
				if nr < 0 || nr >= len(grid) || nc < 0 || nc >= len(grid[nr]) {
					continue
				}
				if grid[nr][nc] == '.' {
					grid[nr][nc] = 'F'
					q = append(q, [2]int{nr, nc})
				}
			}
		}
		if len(q) > 0 {
			minutes++ // the fire reached new grass this minute
		}
	}
	return minutes
}

func main() {
	var grid [][]byte
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		if line := strings.TrimSpace(scanner.Text()); line != "" {
			grid = append(grid, []byte(line))
		}
	}
	fmt.Println(burnMinutes(grid))
